select 'md5 ' || n.nspname || '.' || p.proname || ' ' || md5(rtrim(pg_get_functiondef(p.oid), E'\n')) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where (n.nspname, p.proname) in (('public','ai_try_consume'),('public','ai_cost_add'),('public','ai_refund'),('public','pb_my_plan'),('public','pb_storage_put_ok'),('pb_billing','individual_limits'),('pb_plans','limits'),('public','pb_plan_request'),('public','pb_owner_individual_on'),('pb_billing','has_individual'),('public','pb_owner_billing_setting_set'),('public','pb_owner_billing'),('public','pb_owner_individual_off'),('pb_billing','seats_used'),('public','ai_daily_limit'),('pb_billing','individual_only'),('public','ai_feature_limit')) order by 1;
